function navigate(name,civilTarget=''){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+name));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('topTitle').textContent=pageNames[name]||'TERRAVEX APEX';$('sidebar').classList.remove('open');syncStormFrame();window.scrollTo({top:0,behavior:'smooth'});if(name==='earth')resizeGlobe();if(name==='earthcommand')window.TERRAVEX_EARTH_COMMAND?.enter?.();if(name==='bangladeshsats')window.TERRAVEX_BD_SATELLITE_INTEL?.enter?.();else window.TERRAVEX_BD_SATELLITE_INTEL?.leave?.();if(name==='russiansatbd')window.TERRAVEX_RU_BD_MONITOR?.enter?.();else window.TERRAVEX_RU_BD_MONITOR?.leave?.();if(name==='earthtraffic')window.TERRAVEX_EARTH_TRAFFIC?.resize?.();if(name==='orbitsentinel')window.TERRAVEX_ORBIT_SENTINEL?.enter?.();if(name==='atmoswatch')window.TERRAVEX_ATMOSPHERIC_WATCH?.enter?.();if(name==='intrusionwatch')window.TERRAVEX_INTRUSION_WATCH?.enter?.();if(name==='location')window.TERRAVEX_LOCATION?.enter?.();else window.TERRAVEX_LOCATION?.leave?.();if(name==='radiologicalsafety')window.TERRAVEX_RSC?.enter?.();else window.TERRAVEX_RSC?.leave?.();if(name==='engineering')window.TERRAVEX_ENGINEERING_STUDIO?.enter?.();else window.TERRAVEX_ENGINEERING_STUDIO?.leave?.();if(civilTarget&&name==='earthcommand'){window.setTimeout(()=>{const target=document.getElementById(civilTarget);if(!target)return;target.scrollIntoView({behavior:'smooth',block:'start'});try{target.focus({preventScroll:true})}catch{}target.classList.add('tvx-civil-highlight');window.setTimeout(()=>target.classList.remove('tvx-civil-highlight'),2200);},220);}}
