  function setAggregateLayerFromToggle(key){const cfg=ACTIVITY[key];if(!cfg)return;setActivityVisibility(key,$(cfg.toggle)?.checked===true);if($(cfg.toggle)?.checked&&!S.activityEntities[key]?.length){const label=key==='air'?'WAITING FOR SNAPSHOT':key==='marine'?'MARINE MODEL NOT LOADED':'NO AGGREGATE LOADED';const detail=key==='marine'?'Use Load marine safety layer to fetch broad wave/current model cells. No ship traffic is displayed.':'Enable after loading a source; no placeholder data is drawn.';activityStatus(key,label,detail,'warn');}}
  function loadAllConfiguredActivities(){return Promise.all([loadAggregateLayer('road'),loadMarineConditions(),loadAggregateLayer('drone')]);}
  function renderAircraft(){if(!S.ready)return;const C=window.Cesium;for(const x of S.airEntities.values())S.viewer.entities.remove(x);S.airEntities.clear();const api=window.TERRAVEX_EARTH_TRAFFIC;const rows=api?.getAircraft?.()||[];S.aircraft=rows.filter(a=>Number.isFinite(Number(a.lat))&&Number.isFinite(Number(a.lon))&&a.onGround!==true).slice(0,1800);for(const a of S.aircraft){const id=String(a.id||a.icao24||Math.random().toString(36).slice(2));const alt=Math.max(50,Number(a.geoAltitudeM??a.baroAltitudeM)||900)*1;const entity=S.viewer.entities.add({id:'tve-air-'+id,name:String(a.callsign||a.icao24||id),position:C.Cartesian3.fromDegrees(Number(a.lon),Number(a.lat),alt),point:{pixelSize:4,color:C.Color.ORANGE,outlineColor:C.Color.WHITE,outlineWidth:1},description:'Public ADS-B state-vector snapshot. Position timestamp and receiver coverage vary; not an air-traffic-control display.'});S.airEntities.set(id,entity);}if($('tveLayerAircraft'))for(const e of S.airEntities.values())e.show=$('tveLayerAircraft').checked;text('tveAircraftCount',S.aircraft.length||'—');const snap=api?.getState?.();S.airFetchedAt=snap?.airFetchedAt||null;text('tveAircraftFresh',S.airFetchedAt?'Snapshot '+new Date(S.airFetchedAt).toLocaleTimeString()+' · age/provider dependent':'No snapshot received');text('tveAirSourceState',S.aircraft.length?'OPEN SKY · SNAPSHOT':'NO SNAPSHOT');renderAirDensity(S.aircraft,snap||{});}
  async function refreshAircraft(){const api=window.TERRAVEX_EARTH_TRAFFIC;if(!api||typeof api.refreshAircraftForRegion!=='function'){badge('tveAirSourceState','MODULE UNAVAILABLE','warn');status('Existing Earth Traffic/OpenSky module is not available.','warn');return;}const b=$('tveRefreshAircraft');if(b){b.disabled=true;b.textContent='Requesting public ADS-B…';}text('tveAirSourceState','REQUESTING');try{const ok=await api.refreshAircraftForRegion('bangladesh');renderAircraft();if(ok){audit('Requested Bangladesh ADS-B snapshot');status('OpenSky snapshot received. Its timestamp and request quotas are provider-controlled, not a 1 Hz guarantee.','good');}else{const data=api.getState?.();status('No new aircraft snapshot was obtained. Existing data may be retained, the provider may be rate-limiting, or the current request cooldown may still apply.','warn');} }catch(e){status('Aircraft snapshot could not be refreshed: '+(e.message||e),'bad');}finally{if(b){b.disabled=false;b.textContent='✈ Request Bangladesh aircraft snapshot';}}}
  function locationFix(){if(!window.isSecureContext||!navigator.geolocation){status('Device location requires HTTPS or localhost and browser geolocation support.','warn');return;}status('Requesting one location fix. Approve the browser prompt to continue.');navigator.geolocation.getCurrentPosition(p=>{setLocation({lat:p.coords.latitude,lon:p.coords.longitude,altitude:p.coords.altitude,accuracy:p.coords.accuracy,timestamp:p.timestamp});audit('Received one user-approved device location fix');status('Device position received with browser-reported accuracy ±'+fmt(p.coords.accuracy,0)+' m. The marker is local unless you explicitly select sharing.','good');camera(p.coords.longitude,p.coords.latitude,Math.max(12000,Math.min(900000,Number(p.coords.altitude)||25000)));},e=>status(e.code===1?'Location permission denied. Enable it in browser site settings.':'Device location unavailable: '+e.message,'warn'),{enableHighAccuracy:true,maximumAge:1000,timeout:18000});}
  function startLocationWatch(){if(S.watchId!==null)return;if(!window.isSecureContext||!navigator.geolocation){status('Location watch requires HTTPS or localhost and geolocation support.','warn');return;}S.watchId=navigator.geolocation.watchPosition(p=>{setLocation({lat:p.coords.latitude,lon:p.coords.longitude,altitude:p.coords.altitude,accuracy:p.coords.accuracy,timestamp:p.timestamp});},e=>status('Location watch stopped or unavailable: '+e.message,'warn'),{enableHighAccuracy:true,maximumAge:1000,timeout:25000});$('tveStartLocation').disabled=true;$('tveStopLocation').disabled=false;badge('tveLocationState','TRACKING','live');audit('Started browser location watch');status('Location watch active. Browser/device update cadence is best-effort and may not be once per second.','good');}
  function stopLocationWatch(){if(S.watchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(S.watchId);S.watchId=null;if($('tveStartLocation'))$('tveStartLocation').disabled=false;if($('tveStopLocation'))$('tveStopLocation').disabled=true;badge('tveLocationState',S.location?'LAST FIX':'STOPPED',S.location?'live':'warn');audit('Stopped browser location watch');status('Location watch stopped. The last received fix remains visible until the panel is cleared.');}
  function loadOutbox(){try{const v=JSON.parse(localStorage.getItem(STORAGE)||'[]');S.outbox=Array.isArray(v)?v.filter(x=>x&&typeof x.id==='string'&&typeof x.text==='string').slice(0,100):[]}catch{S.outbox=[];}renderOutbox();}
  function saveOutbox(){try{localStorage.setItem(STORAGE,JSON.stringify(S.outbox.slice(0,100)));return true;}catch{return false;}}
  function renderOutbox(){const host=$('tveOutboxList');if(!host)return;host.replaceChildren();if(!S.outbox.length){const p=document.createElement('div');p.className='muted';p.textContent='No queued messages.';host.append(p);return;}for(const item of S.outbox){const row=document.createElement('div');row.className='tve-outbox-item';const body=document.createElement('div'),title=document.createElement('b'),msg=document.createElement('p'),meta=document.createElement('small'),state=document.createElement('span');title.textContent=item.to||'Unspecified recipient';msg.textContent=item.text;meta.textContent=new Date(item.createdAt).toLocaleString();state.className='tve-outbox-state';state.textContent=item.sentAt?'SENT TO PEER':'QUEUED LOCALLY';body.append(title,msg,meta,state);const remove=document.createElement('button');remove.type='button';remove.className='btn small-button';remove.textContent='Remove';remove.addEventListener('click',()=>{S.outbox=S.outbox.filter(x=>x.id!==item.id);saveOutbox();renderOutbox();});row.append(body,remove);host.append(row);}}
  function queueMessage(){const to=String($('tveMsgRecipient')?.value||'').trim(),body=String($('tveMsgBody')?.value||'').trim();if(!body)return status('Write a message first.','warn');if(body.length>3000)return status('Message exceeds the 3000-character limit.','warn');if(S.outbox.length>=100)return status('Outbox limit reached (100). Remove old messages before adding more.','warn');const item={id:(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)),to,text:body,createdAt:new Date().toISOString(),sentAt:null};S.outbox.unshift(item);if(!saveOutbox()){S.outbox.shift();return status('Browser storage is unavailable or full. The message was not queued.','bad');}$('tveMsgBody').value='';renderOutbox();audit('Queued local message for '+(to||'unlabelled recipient'));status('Message saved in this browser’s local outbox. It has not been delivered.','good');}
  function sendCurrentLocation(){if(!S.location)return status('Get a GPS fix first. No location has been sent.','warn');const api=window.TERRAVEX_SPACE_COMMS;if(!api||typeof api.sendLocation!=='function')return status('The existing Space Communications module is unavailable.','warn');const ok=api.sendLocation({lat:S.location.lat,lon:S.location.lon,accuracy:S.location.accuracy,timestamp:S.location.at});if(ok){audit('Shared current device location with connected peer');status('Current position sent to the connected browser peer. This is not an emergency-service dispatch.','good');}else status('No peer data channel is open. The location was not sent.','warn');}
  function sendOutbox(){const api=window.TERRAVEX_SPACE_COMMS;if(!api||typeof api.sendText!=='function')return status('The existing Space Communications module is unavailable.','warn');const pending=S.outbox.filter(x=>!x.sentAt);if(!pending.length)return status('There are no queued messages waiting to send.','warn');let sent=0;for(const item of pending){const label=item.to?'['+item.to+'] ':'',ok=api.sendText(label+item.text);if(!ok)break;item.sentAt=new Date().toISOString();sent++;}saveOutbox();renderOutbox();audit('Sent '+sent+' queued message(s) to current peer');status(sent?sent+' message(s) handed to the currently connected browser peer. Delivery confirmation is not implied.':'No peer data channel is open. Messages remain queued locally.',sent?'good':'warn');}
  function updateStatuses(){const online=navigator.onLine!==false;badge('tveNetworkBadge',online?'BROWSER ONLINE':'BROWSER OFFLINE',online?'live':'warn');const sat=window.TERRAVEX_SATELLITE_TRACKER?.getState?.();if(sat){text('tveOrbitSourceState',sat.records?'PUBLIC ORBITS · READY':'NOT LOADED');if(!S.satellites.length&&sat.records)text('tveSatFresh',sat.records+' tracker records available · click load to plot');}const btcl=window.TERRAVEX_BTCL_SIGNAL_HUB?.getSnapshot?.();text('tveBtclState',btcl?(btcl.source==='live'?'PROVIDER DATA MODE':'DEMO / NOT A LIVE LINK'):'MODULE UNAVAILABLE');const secure=window.TERRAVEX_SECURELINK?.getState?.();text('tveSecureState',secure?.last?.serviceState||'NOT VERIFIED');const comm=window.TERRAVEX_SPACE_COMMS?.getState?.();const peer=comm?.peerConnected===true;text('tvePeerState',peer?'CONNECTED':'DISCONNECTED');badge('tvePeerState',peer?'PEER LINK OPEN':'NO PEER',peer?'live':'warn');badge('tveCommsBadge',peer?'PEER CONNECTED':'NO PEER',peer?'live':'warn');text('tvePeerFresh',peer?'Browser-to-browser data channel open':'Open Space Communications to pair peers');if(secure?.last?.serviceState==='HEALTHY')text('tveSecureState','HTTPS HEALTH CHECK HEALTHY');else if(secure?.last?.serviceState==='INCONCLUSIVE')text('tveSecureState','INCONCLUSIVE');if(btcl?.source==='live')text('tveBtclState','AUTHORIZED FEED CONFIGURED · VERIFY DEVICE');else if(btcl)text('tveBtclState','SIMULATION MODE');if($('tveLayerAircraft')?.checked!==false)for(const e of S.airEntities.values())e.show=true;}
  function loadExternalTiles(){if(!S.ready)return status('3D engine is not ready.','warn');const raw=String($('tveTilesUrl')?.value||'').trim();let url;try{url=new URL(raw);if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||!/(tileset\.json|\.json)$/i.test(url.pathname))throw new Error('Use a full HTTPS tileset.json URL without credentials, query string or fragment.');const h=url.hostname.toLowerCase();if(h==='localhost'||h.endsWith('.local')||h.endsWith('.internal')||/^\d{1,3}(\.\d{1,3}){3}$/.test(h))throw new Error('Local IP/hostname endpoints are not accepted in this public page.');}catch(e){text('tveTilesState',e.message||'Invalid URL');return;}const b=$('tveLoadTiles');if(b){b.disabled=true;b.textContent='Loading tileset…';}Cesium.Cesium3DTileset.fromUrl(url.href).then(tileset=>{if(S.externalTileset)S.viewer.scene.primitives.remove(S.externalTileset);S.externalTileset=tileset;S.viewer.scene.primitives.add(tileset);$('tveRemoveTiles').disabled=false;badge('tveEarth2Badge','EXTERNAL TILESET LOADED','live');text('tveTilesState','External 3D Tileset loaded. It is an authorized endpoint, not automatically an Earth2 connection. CORS, credentials and provider terms remain the provider’s responsibility.');audit('Loaded authorized external 3D Tileset');}).catch(e=>{badge('tveEarth2Badge','TILESET UNAVAILABLE','warn');text('tveTilesState','Could not load external tileset: '+(e.message||e)+'. Verify tileset.json, HTTPS, CORS, asset access and provider permission.');}).finally(()=>{if(b){b.disabled=false;b.textContent='Load external 3D Tiles';}});}
  async function applyTerrain(){if(!S.ready)return;const token=String($('tveIonToken')?.value||'').trim();if(!token){text('tveTerrainState','Paste a domain-restricted Cesium ion browser token first.');return;}try{window.Cesium.Ion.defaultAccessToken=token;text('tveTerrainState','Requesting Cesium World Terrain…');const terrain=await window.Cesium.Terrain.fromWorldTerrain();S.viewer.scene.setTerrain(terrain);S.terrain='ion';badge('tveTerrainBadge','WORLD TERRAIN ACTIVE','live');text('tveTerrainState','World terrain loaded. The browser token is held in memory only. Restrict it to your GitHub Pages origin in Cesium ion.');audit('Applied user-supplied Cesium terrain token');}catch(e){S.terrain='ellipsoid';badge('tveTerrainBadge','TERRAIN UNAVAILABLE','warn');text('tveTerrainState','Terrain was not enabled: '+(e.message||e)+'. Check the token, asset access and network. The base globe remains active.');}}
  // v39: civil environmental / humanitarian panels reuse the existing Cesium viewer.
  const CIVIL={entities:{flood:[],humanitarian:[],forest:[]},flood:null,humanitarian:null,forest:null,archiveItems:[],archiveBusy:false,busy:{flood:false,humanitarian:false,forest:false},archiveLayer:null};
